<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='testing'||getenv('WK_TEST_ALLOW_WRITES')!=='1'||!preg_match('/^waithaka_test_[a-z0-9_]+_test$/D',(string)getenv('DB_DATABASE'))){fwrite(STDERR,"Use an isolated, freshly prepared test database.\n");exit(2);}
require dirname(__DIR__).'/app/bootstrap.php';
require __DIR__.'/mail_feedback_fixture.php';
$checks=0;
function feedback_db_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);$GLOBALS['checks']++;}
$CONFIG['mail']['sns_topic_arn']='arn:aws:sns:us-east-1:111122223333:website-fixture';
$CONFIG['mail']['transport']='disabled';
[$key,$pem]=feedback_fixture_signer();$loader=fn()=>$pem;
$prefix='feedback-'.bin2hex(random_bytes(6));$counter=0;
$make=static function(string $suffix,string $state='sent',bool $provider=true)use($prefix):array{
    $email=$prefix.'-'.$suffix.'@example.invalid';$dedupe=$prefix.'-'.$suffix;
    $id=enqueue_email($email,'Synthetic feedback test','<p>Fixture only.</p>',$dedupe);
    $providerId='ses-fixture-'.$id;
    db()->prepare('UPDATE email_outbox SET status=?,attempts=1,provider_id=?,sent_at=NOW() WHERE id=?')->execute([$state,$provider?$providerId:null,$id]);
    return ['id'=>$id,'email'=>$email,'dedupe'=>hash('sha256',$dedupe),'provider'=>$providerId];
};
$send=static function(array $item,string $type,array $changes=[])use($key,$loader):array {
    $event=['eventType'=>$type,'mail'=>['messageId'=>$item['provider'],'destination'=>[$item['email']],'tags'=>['delivery-key'=>[$item['dedupe']]]]];
    if($type==='Delivery')$event['delivery']=['recipients'=>[$item['email']]];
    elseif($type==='Bounce')$event['bounce']=['bounceType'=>'Permanent','bouncedRecipients'=>[['emailAddress'=>$item['email']]]];
    else $event['complaint']=['complainedRecipients'=>[['emailAddress'=>$item['email']]]];
    $event=array_replace_recursive($event,$changes);
    $envelope=mail_feedback_verify(feedback_fixture_signed(feedback_fixture_message($event),$key),$loader);
    return [$envelope,mail_feedback_apply($envelope)];
};
$item=$make('primary');
db()->prepare("INSERT INTO newsletter_subscribers(email,status,consent_version,requested_at,confirmed_at,created_at,updated_at) VALUES(?,'confirmed','fixture',NOW(),NOW(),NOW(),NOW())")->execute([$item['email']]);$subscriber=(int)db()->lastInsertId();
[$envelope,$result]=$send($item,'Delivery');
feedback_db_check($result['feedback']==='delivered','An authenticated delivery must update the matched recipient.');
feedback_db_check(mail_feedback_apply($envelope)['action']==='duplicate','Repeated SNS message IDs must be idempotent.');
feedback_db_check(!email_address_suppressed($item['email']),'Successful delivery must not suppress an address.');
[$envelope,$result]=$send($item,'Bounce');
feedback_db_check($result['suppressed']&&email_address_suppressed(strtoupper($item['email'])),'A permanent bounce must suppress the exact normalized recipient.');
$row=newsletter_subscriber($subscriber);
feedback_db_check($row['status']==='suppressed'&&$row['suppression_reason']==='hard_bounce'&&(int)$row['consent_revision']===2,'Provider suppression must invalidate existing newsletter consent snapshots.');
$revision=(int)$row['consent_revision'];mail_feedback_apply($envelope);
feedback_db_check((int)newsletter_subscriber($subscriber)['consent_revision']===$revision,'Duplicate feedback must not mutate consent twice.');
$queued=enqueue_email($item['email'],'Do not send','<p>Fixture only.</p>',$prefix.'-after-bounce');
$sent=0;$stats=email_work(50,function()use(&$sent){$sent++;return 'unexpected';});
feedback_db_check($sent===0&&$stats['suppressed']===1,'A suppressed address must not reach the provider transport.');
$before=(int)db()->query('SELECT COUNT(*) FROM email_outbox')->fetchColumn();newsletter_request_signup($item['email'],'Fixture');
feedback_db_check((int)db()->query('SELECT COUNT(*) FROM email_outbox')->fetchColumn()===$before,'A new signup must not bypass authenticated provider suppression.');
$token=newsletter_create_token($subscriber,'confirm',date('Y-m-d H:i:s',time()+3600));
feedback_db_check(!newsletter_apply_token($token,'confirm'),'Confirmation tokens cannot clear provider suppression.');
[$envelope,$result]=$send($item,'Complaint');
feedback_db_check($result['feedback']==='complained'&&newsletter_subscriber($subscriber)['suppression_reason']==='complaint','A complaint must supersede delivery and bounce feedback.');
[$envelope,$result]=$send($item,'Delivery');
feedback_db_check($result['feedback']==='complained'&&email_address_suppressed($item['email']),'A late delivery event must not clear a complaint.');
$suppression=db()->query('SELECT email_encrypted FROM mail_suppressions LIMIT 1')->fetchColumn();
feedback_db_check(!str_contains($suppression,$item['email']),'Suppressed addresses must be encrypted at rest.');
$temporary=$make('temporary');$send($temporary,'Bounce',['bounce'=>['bounceType'=>'Transient']]);
feedback_db_check(!email_address_suppressed($temporary['email']),'A transient bounce must not become permanent address suppression.');
$wrong=$make('wrong-recipient');[$envelope,$result]=$send($wrong,'Complaint',['complaint'=>['complainedRecipients'=>[['emailAddress'=>'somebody-else@example.invalid']]]]);
feedback_db_check($result['action']==='recipient_mismatch'&&!email_address_suppressed($wrong['email']),'Feedback must bind to the immutable outbox recipient.');
$wrongTag=$make('wrong-tag');[$envelope,$result]=$send($wrongTag,'Complaint',['mail'=>['tags'=>['delivery-key'=>[str_repeat('a',64)]]]]);
feedback_db_check($result['action']==='unmatched_delivery'&&!email_address_suppressed($wrongTag['email']),'A matching provider ID with a conflicting delivery tag must be refused.');
$ambiguous=$make('ambiguous','ambiguous',false);[$envelope,$result]=$send($ambiguous,'Delivery');
$row=db()->query('SELECT status,provider_id,feedback_status FROM email_outbox WHERE id='.$ambiguous['id'])->fetch();
feedback_db_check($row['status']==='sent'&&$row['provider_id']===$ambiguous['provider']&&$row['feedback_status']==='delivered','Verified feedback may reconcile an unknown send without resending it.');
$pending=$make('never-sent','pending',false);[$envelope,$result]=$send($pending,'Delivery');
feedback_db_check($result['action']==='unmatched_delivery','A never-sent outbox entry cannot be claimed by a feedback tag.');
db()->prepare("UPDATE email_outbox SET status='suppressed' WHERE id=?")->execute([$pending['id']]);
$subscription=feedback_fixture_message([],['Type'=>'SubscriptionConfirmation','Token'=>'synthetic-subscription-capability','SubscribeURL'=>'https://sns.us-east-1.amazonaws.com/?Action=ConfirmSubscription&Token=synthetic','Message'=>'Synthetic confirmation']);
$signed=mail_feedback_verify(feedback_fixture_signed($subscription,$key),$loader);
feedback_db_check(mail_feedback_apply($signed)['action']==='confirmation_pending','A signed subscription request must wait for the Writer confirmation action.');
$row=db()->query('SELECT status,token_encrypted FROM mail_feedback_subscriptions')->fetch();
feedback_db_check($row['status']==='pending'&&!str_contains($row['token_encrypted'],'synthetic-subscription-capability'),'Subscription capabilities must be encrypted and not automatically followed.');
feedback_db_check(mail_feedback_apply($signed)['action']==='duplicate','Subscription notifications must also deduplicate.');
$settings=app_config('db');$other=new PDO('mysql:host='.$settings['host'].';port='.$settings['port'].';dbname='.$settings['name'].';charset=utf8mb4',$settings['user'],$settings['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
feedback_db_check(email_recipient_lock($temporary['email'],0),'The active sender must acquire its recipient lock.');
$lockName='wk-mail-'.substr(email_address_hash($temporary['email']),0,56);
$q=$other->prepare('SELECT GET_LOCK(?,0)');$q->execute([$lockName]);feedback_db_check((int)$q->fetchColumn()===0,'A competing connection cannot suppress or send through an in-flight recipient lock.');
email_recipient_unlock($temporary['email']);$q->execute([$lockName]);feedback_db_check((int)$q->fetchColumn()===1,'The recipient lock must be released after completion.');
$other->prepare('SELECT RELEASE_LOCK(?)')->execute([$lockName]);
echo "Mail feedback database checks passed: $checks\n";
